using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = new ReportingConfiguration(
            storageRootPath: Path.Combine(Directory.GetCurrentDirectory(), "eval-results"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Greeting_ShouldBeCoherentAndRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await using var session = await _reportingConfig.CreateSessionAsync(
            scenario: nameof(Greeting_ShouldBeCoherentAndRelevant));

        var result = await session.EvaluateAsync(messages, _evaluatorClient);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 3);
        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 3);
    }

    [TestMethod]
    public async Task FactualQuestion_ShouldBeGrounded()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await using var session = await _reportingConfig.CreateSessionAsync(
            scenario: nameof(FactualQuestion_ShouldBeGrounded));

        var result = await session.EvaluateAsync(messages, _evaluatorClient);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 4);
        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 4);
        AssertMetricAboveThreshold(result, nameof(GroundednessEvaluator), 4);
    }

    [TestMethod]
    public async Task MultiTurn_ShouldMaintainContext()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await using var session = await _reportingConfig.CreateSessionAsync(
            scenario: nameof(MultiTurn_ShouldMaintainContext));

        var result = await session.EvaluateAsync(messages, _evaluatorClient);
        AssertMetricAboveThreshold(result, nameof(CoherenceEvaluator), 4);
        AssertMetricAboveThreshold(result, nameof(RelevanceEvaluator), 4);
    }

    private static void AssertMetricAboveThreshold(
        EvaluationResult result,
        string metricName,
        double threshold)
    {
        var metric = result.Metrics.FirstOrDefault(m =>
            m.Key.Contains(metricName, StringComparison.OrdinalIgnoreCase));

        Assert.IsTrue(
            metric.Value is NumericMetric numeric && numeric.Value >= threshold,
            $"Metric '{metricName}' did not meet threshold {threshold}.");
    }
}

